#include <gtest/gtest.h>
#include <string>

class ParserTest : public ::testing::Test {
 protected:
  std::string input = "alpha,beta";
};

TEST_F(ParserTest, ParsesFields) {
  EXPECT_FALSE(input.empty());
}

